class Solution {
public:
    int minArrayLength(vector<int>& nums, int k) {
        int n = nums.size();

        // A zero allows the entire array to collapse.
        for (int x : nums) {
            if (x == 0)
                return 1;
        }

        int ans = 1;
        long long product = nums[0];

        for (int i = 1; i < n; ++i) {
            if (product * nums[i] <= k) {
                // Merge adjacent elements.
                product *= nums[i];
            } else {
                // Start a new segment.
                ++ans;
                product = nums[i];
            }
        }

        return ans;
    }
};
